INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") VALUES ('G01',1,NULL,'المجموعة الأولى : الثقافة والترفيه (المنظمات والأنشطة المتخصصة في الثقافة والترفيه)',1);
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G01-A01',2,"id",'الثقافة والفنون',1 FROM "ncnp_classifications" WHERE "code"='G01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B01',3,"id",'منظمات فنون العمارة والتصميم','المنظمات التي تعنى بأنشطة فنون العمارة والتصميم وتطويرها والمحافظة عليها بجميع صورها، وتشمل التصميم المعماري، والتصميم الداخلي، والتصميم الحضري والمدني، وتصميم الحدائق والتشجير، وتصميم المناظر الطبيعية، وما يرتبط بها من أعمال وخدمات.','وزارة الثقافة',1 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B02',3,"id",'منظمات الفنون البصرية','المنظمات التي تعنى بالأنشطة المتعلقة بالفنون البصرية وإنشائها وإعدادها وإنتاجها وتطويرها ونشر محتواها، وتشمل اللوحات والرسومات والمنحوتات والصور الفوتوغرافية والخط ونحوها.','وزارة الثقافة',2 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B03',3,"id",'منظمات الأفلام','المنظمات التي تعنى بالأنشطة المتعلقة بالأفلام -بجميع صورها- وإنشائها وإنتاجها وتطويرها ونشر محتواها، ويشمل ذلك كتابة السيناريو وأفكار إنتاج الأفلام والفيديوهات، ونحوها.','وزارة الثقافة',3 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B04',3,"id",'منظمات الموسيقى','المنظمات التي تعنى بالأنشطة المتعلقة بالموسيقى وإنتاجها وتطويرها ونشر محتواها بمختلف صورها، بما في ذلك العروض الحية والمسجلة والموسيقى الرقمية والتسجيلات الموسيقية، والابتكارات الصوتية وغيرها.','وزارة الثقافة',4 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B05',3,"id",'منظمات الأزياء','المنظمات التي تعنى بأنشطة تصميم الأزياء وتطويرها وإنتاجها وعرضها والمحافظة عليها، وما يرتبط بها من مواد أولية وكماليات ونحوها، ويشمل ذلك الأزياء التقليدية والتراثية والعصرية وغيرها.','وزارة الثقافة',5 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B06',3,"id",'منظمات التراث','المنظمات التي تعنى بالأنشطة المتعلقة بالتراث والآثار، من حيث استكشافها وحمايتها وصيانتها وتهيئتها وترميمها وإدارتها والمحافظة عليها، ويشمل ذلك المدن والقرى والأحياء والمباني التراثية والحرف والصناعات التقليدية والمعالم التاريخية، والتراث غير المادي.','وزارة الثقافة',6 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B07',3,"id",'منظمات المتاحف','المنظمات التي تعنى بالأنشطة المتعلقة بالمتاحف وإنشائها وتطويرها وصيانتها والمحافظة على طابعها الفني والأثري، بما في ذلك البنية الأساسية المادية لها','وزارة الثقافة',7 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B08',3,"id",'منظمات المسرح والفنون الأدائية','المنظمات التي تعنى بالأنشطة المتعلقة بالمسارح وأماكن العرض وتنظيمها، والأنشطة المتعلقة بالفنون الأدائية بجميع صورها وإنتاجها وتطويرها ونشر محتواها، وتشمل المسرحيات وعروض الأوبرا والأداء الحي والعروض الشخصية في المسارح –(ستاند آب كوميدي)- والأماكن العامة ونحوها.','وزارة الثقافة',8 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B09',3,"id",'منظمات فنون الطهي','المنظمات التي تعنى بالأنشطة المتعلقة بفنون الطهي، وتطويرها والمحافظة عليها وتشجيع والابتكار فيها، ويشمل ذلك تقنيات الطهي، ووصفات الطعام، والمقادير، ومصادر المكونات، وإعداد الطعام وتقديمه.','وزارة الثقافة',9 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B10',3,"id",'منظمات النشر','المنظمات التي تشمل الأنشطة المتعلقة بالنشر الثقافي بمختلف وسائطه؛ وخصوصاً الكتب، ومعارضها.','وزارة الثقافة',10 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B11',3,"id",'منظمات الأدب','المنظمات التي تعنى بالأنشطة المتعلقة بالأعمال الأدبية.','وزارة الثقافة',11 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B12',3,"id",'منظمات الترجمة','المنظمات التي تعنى بأنشطة بالترجمة من اللغة العربية إلى غيرها، ومن مختلف اللغات إلى العربية.','وزارة الثقافة',12 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B13',3,"id",'منظمات المكتبات','المنظمات التي تعنى بالأنشطة المتعلقة بالمكتبات وإنشائها وتطويرها وتأهيلها والعناية بخدماتها ومقتنياتها وتجهيزاتها الأساسية لتحقيق أهدافها، ويشمل ذلك المكتبات العامة والخاصة وغير الربحية.','وزارة الثقافة',13 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B14',3,"id",'متاحف العلوم والتقنية','المتاحف المتخصصة في مجالات العلوم والتقنية','مدينة الملك عبدالعزيز للعلوم والتقنية',14 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A01-B15',3,"id",'حدائق الحيوان والمتنزهات والأحواض المائية','الخدمات المختصه بالمتنزهات والأحواض المائية وحدائق الحيوان','وزارة البيئة والمياه والزراعة',15 FROM "ncnp_classifications" WHERE "code"='G01-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G01-A02',2,"id",'الرياضة',2 FROM "ncnp_classifications" WHERE "code"='G01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A02-B01',3,"id",'الألعاب الرياضية','تقديم الرياضة للهواة والتدريب واللياقة البدنية والمسابقات والاحداث الرياضة والنوادي الرياضية بما فيها الرياضات الذهنية والدراجات الهوائية والسيارات ومراكز اللياقة البدنية','وزارة الرياضة',1 FROM "ncnp_classifications" WHERE "code"='G01-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G01-A03',2,"id",'الهوايات والخدمات الترفيهية',3 FROM "ncnp_classifications" WHERE "code"='G01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A03-B01',3,"id",'الهوايات','المنظمات التي تعني بتطوير قطاع الهوايات والأنشطة والفعاليات المرتبطة به بما في ذلك اندية الهواة','مركز جودة الحياة',1 FROM "ncnp_classifications" WHERE "code"='G01-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A03-B02',3,"id",'السفر والجولات السياحية','المنظمات التي تقدم خدمات وكالات السفر والسياحة، وتنظيم الرحلات السياحية، وترتيب الحجوزات للفنادق، والإرشاد السياحي، وتوعية المستفيدين بأساليب السفر وثقافته','وزارة السياحة',2 FROM "ncnp_classifications" WHERE "code"='G01-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G01-A03-B03',3,"id",'الخدمات الترفيهية','المنظمات التي تقدم الفعاليات والتسهيلات والخدمات الترفيهية للأفراد والمجتمعات بما في ذلك المراكز الترفيهية','الهيئة العامة للترفية',3 FROM "ncnp_classifications" WHERE "code"='G01-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") VALUES ('G02',1,NULL,'المجموعة الثانية التعليم والأبحاث (المنظمات والأنشطة التي تقود وتدير وتقدم وتشجع وتدعم الخدمات التعليمية والبحثية)',2);
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G02-A01',2,"id",'التعليم الابتدائي والاعدادي والثانوي',1 FROM "ncnp_classifications" WHERE "code"='G02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A01-B01',3,"id",'التعليم الابتدائي والاعدادي والثانوي','التعليم في المستوى الابتدائي والإعدادي والثانوي بما في ذلك التعليم قبل الابتدائي ما عدا دور رعاية الأطفال','وزارة التعليم',1 FROM "ncnp_classifications" WHERE "code"='G02-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G02-A02',2,"id",'التعليم العالي (المراحل الجامعية)',2 FROM "ncnp_classifications" WHERE "code"='G02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A02-B01',3,"id",'التعليم العالي (المراحل الجامعية)','التعليم العالي الذي يقدم درجات علمية ويشمل الجامعات والكليات بأنواعها','وزارة التعليم',1 FROM "ncnp_classifications" WHERE "code"='G02-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G02-A03',2,"id",'مؤسسات التعليم الأخرى',3 FROM "ncnp_classifications" WHERE "code"='G02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A03-B01',3,"id",'رعاية الموهبة والموهبين','المنظمات التي تدعم وتطور بيئة الابداع وتمكين الموهوبين بفئاتهم المختلفة','وزارة التعليم',1 FROM "ncnp_classifications" WHERE "code"='G02-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A03-B02',3,"id",'التعليم المستمر/ الكبار','المنظمات التي تعمل في توفير التعليم والتدريب إضافة إلى نظام التعليم الرسمي، وتشمل التعلم عن بعد والمدارس المسائية وبرامج محو الأمية والقراءة','وزارة التعليم',2 FROM "ncnp_classifications" WHERE "code"='G02-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G02-A04',2,"id",'الأبحاث',4 FROM "ncnp_classifications" WHERE "code"='G02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A04-B01',3,"id",'خدمات الأبحاث الطبية','الأبحاث في الميادين الطبية، بما في ذلك الأبحاث المتعلقة بأمراض معيَّنة أو مشاكل صحية معينة أو تخصصات طبية','مدينة الملك عبدالعزيز للعلوم والتقنية',1 FROM "ncnp_classifications" WHERE "code"='G02-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A04-B02',3,"id",'خدمات أبحاث النقل والسلامة','المنظمات المختصة بالبحث العلمي وتبادل المعلومات في مجالات النقل والسلامة','وزارة النقل والخدمات اللوجستية',2 FROM "ncnp_classifications" WHERE "code"='G02-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A04-B03',3,"id",'خدمات الأبحاث العلوم والتقنية','الأبحاث في مجالات العلوم والتقنية','مدينة الملك عبدالعزيز للعلوم والتقنية',3 FROM "ncnp_classifications" WHERE "code"='G02-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A04-B04',3,"id",'منظمات الأبحاث في البيانات والذكاء الاصطناعي','المنظمات التي تعني بالأنشطة المتعلقة بالتحليل واعداد الأبحاث والدراسات والتجارب والتطوير والابتكار في مجال البيانات و الذكاء الاصطناعي.','الهيئة السعودية للبيانات والذكاء الاصطناعي',4 FROM "ncnp_classifications" WHERE "code"='G02-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A04-B05',3,"id",'أبحاث العلوم الاجتماعية ودراسات السياسات الاجتماعية ونحوها','البحث والتحليل في مجال العلوم الاجتماعية والسياسات الاجتماعية ونحوها','وزارة الموارد البشرية والتنمية الاجتماعية',5 FROM "ncnp_classifications" WHERE "code"='G02-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A04-B06',3,"id",'أبحاث دراسات السياسات الاقتصادية ونحوها','البحث والتحليل في مجال السياسات الاقتصادية ونحوها','وزارة الاقتصاد والتخطيط',6 FROM "ncnp_classifications" WHERE "code"='G02-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A04-B07',3,"id",'أبحاث بيئية ومائية وزراعية','البحث والتحليل في مجال البيئة و الزراعة ونحوها','مدينة الملك عبدالعزيز للعلوم والتقنية',7 FROM "ncnp_classifications" WHERE "code"='G02-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G02-A05',2,"id",'البيانات والذكاء الاصطناعي',5 FROM "ncnp_classifications" WHERE "code"='G02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A05-B01',3,"id",'منظمات البيانات والذكاء الاصطناعي','المنظمات التي تعني بالأنشطة المتعلقة بالبيانات والذكاء الاصطناعي والخدمات ذات العلاقة بها مثل تقديم استشارات وبناء القدرات في المجال','الهيئة السعودية للبيانات والذكاء الاصطناعي',1 FROM "ncnp_classifications" WHERE "code"='G02-A05';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G02-A06',2,"id",'تقنية المعلومات',6 FROM "ncnp_classifications" WHERE "code"='G02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A06-B01',3,"id",'التقنيات والمنهجيات','خدمات دعم تقنيات ومنهجيات إنشاء صفحات الإنترنت و تقنيات إنتاج المحتوى وتحريره وألعاب الفيديو والوسائط المتعددة ،و تأليف صفحات الويب وحزم النشر و تصميم الرسومات ،و تقنيات تحليل وتعدين البيانات وذكاء الاعمال ،وأنظمة دعم القرار وإدارة قواعد البيانات ، و دعم التقنيات الناشئة في عالم تقنية المعلومات والاتصالات والروبوتات و التقنية التي تدعم الإنتاجية الشخصية بما في ذلك مجموعات تصميم الرسومات والوسائط المتعددة والسحب الإلكترونية و تقنيات الأجهزة المادية وأجهزة الاستشعار والكشف.','وزارة الاتصالات وتقنية المعلومات',1 FROM "ncnp_classifications" WHERE "code"='G02-A06';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G02-A06-B02',3,"id",'أمن المعلومات والتطوير الاحترافي للتقنية والاتصالات','خدمات تقنيات أمن المعلومات والتحكم و دعم المنهجيات والتأهيل والتطوير الاحترافية للتقنية والاتصالات','وزارة الاتصالات وتقنية المعلومات',2 FROM "ncnp_classifications" WHERE "code"='G02-A06';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") VALUES ('G03',1,NULL,'المجموعة الثالثة الصحة (المنظمات التي تعمل في الأنشطة التي لها علاقة بالصحة وتوفير الرعاية الصحية ، سواء الخدمات العامة أو المتخصصة، إدارة خدمات الرعاية الصحية، خدمات الدعم الصحي)',3);
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G03-A01',2,"id",'دور الرعاية الصحية والتمريض',1 FROM "ncnp_classifications" WHERE "code"='G03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A01-B01',3,"id",'دور الرعاية الصحية والتمريض','دور النقاهة والرعاية المنزلية وكذلك خدمات الرعاية الصحية الأوَّلية، وتشمل دور الرعاية لأمراض الشيخوخة وللمعاقين شديدي الإصابة','وزارة الصحة',1 FROM "ncnp_classifications" WHERE "code"='G03-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G03-A02',2,"id",'المستشفيات والمراكز الطبية',2 FROM "ncnp_classifications" WHERE "code"='G03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A02-B01',3,"id",'المستشفيات','خدمات المعالجة الأولية والرعاية الصحية داخل المستشفيات','وزارة الصحة',1 FROM "ncnp_classifications" WHERE "code"='G03-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A02-B02',3,"id",'المراكز المتخصصة','خدمات الرعاية الصحية داخل المراكز الطبية المتخصصة للأشخاص الذين يحتاجون إلى خدمات المراكز المتخصصة مثل: مراكز غسيل الكلي، التأهيل الطبي،العلاج الطبيعي وغيرها','وزارة الصحة',2 FROM "ncnp_classifications" WHERE "code"='G03-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G03-A03',2,"id",'الصحة النفسية والتدخل في الازمات',3 FROM "ncnp_classifications" WHERE "code"='G03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A03-B01',3,"id",'مستشفيات الأمراض النفسية','الرعاية داخل المستشفى والعلاج لمرضى الأمراض النفسية','وزارة الصحة',1 FROM "ncnp_classifications" WHERE "code"='G03-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A03-B02',3,"id",'خدمات علاج الأمراض النفسية','العلاج خارج المستشفيات لمرضى الأمراض العقلية، بما في ذلك مراكز الرعاية الصحية النفسية ودور الرعاية المتوسطة (منازل منتصف الطريق للمرضى النفسيين)','وزارة الصحة',2 FROM "ncnp_classifications" WHERE "code"='G03-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A03-B03',3,"id",'خدمات التدخل في الأزمات والحماية','خدمات خارج المستشفى والمشورة في حالات الصحة النفسية الحادة، بما في ذلك العلاج لمنع إيذاء الذات ودعم ضحايا الاعتداءات أو الاستغلال','وزارة الموارد البشرية والتنمية الاجتماعية',3 FROM "ncnp_classifications" WHERE "code"='G03-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G03-A04',2,"id",'الخدمات الصحية الأخرى',4 FROM "ncnp_classifications" WHERE "code"='G03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A04-B01',3,"id",'الخدمات الصحية العامة','هي الخدمات الصحية التي تقدم مجموعة من الأنشطة العلاجية أو التوعوية أو التثقيفية أو التأهيلية في تخصصات مختلفة','وزارة الصحة',1 FROM "ncnp_classifications" WHERE "code"='G03-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A04-B02',3,"id",'الخدمات الصحية المتخصصة','هي الخدمات الصحية التي تقدم مجموعة من الأنشطة العلاجية أو التوعوية أو التثقيفية أو التأهيلية في تخصص واحد','وزارة الصحة',2 FROM "ncnp_classifications" WHERE "code"='G03-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A04-B03',3,"id",'خدمات العلاج التكميلي والطب البديل','خدمات العلاج والتثقيف للعلاج التكميلي والطب البديل','وزارة الصحة',3 FROM "ncnp_classifications" WHERE "code"='G03-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A04-B04',3,"id",'خدمات دعم المرضى وذويهم','خدمات تقديم الدعم النفسي والاجتماعي والمادي لفئات معينة من المرضى وأسرهم','وزارة الصحة',4 FROM "ncnp_classifications" WHERE "code"='G03-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A04-B05',3,"id",'الخدمات الطبية المساندة','تقديم خدمات طبية مساندة مثل الاشعة ، التمريض ، المختبرات','وزارة الصحة',5 FROM "ncnp_classifications" WHERE "code"='G03-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G03-A04-B06',3,"id",'الخدمات الطبية الطارئة','الخدمات للأشخاص الذين يحتاجون رعاية مباشرة، بما في ذلك خدمات الإسعاف والرعاية في حالات الطوارئ من قِبَل الفنيين الصحيين، وبرامج الصدمات، وبرامج الرعاية لليائسين، وخدمات الإسعاف','وزارة الصحة',6 FROM "ncnp_classifications" WHERE "code"='G03-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") VALUES ('G04',1,NULL,'المجموعة الرابعة الخدمات الاجتماعية (المنظمات التي تقدم خدمات إنسانية واجتماعية للمجتمع لفئات مستهدفة)',4);
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G04-A01',2,"id",'خدمات الفئات الاجتماعية',1 FROM "ncnp_classifications" WHERE "code"='G04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A01-B01',3,"id",'خدمات الرعاية وخدمات الأطفال','المنظمات التي توفر رعاية وخدمات الأطفال والأيتام، كخدمات الاحتضان والأسر البديلة ومراكز تنمية الطفل، ودور الرعاية، بما في ذلك مراكز رعاية الرُضَّع ورياض الأطفال','وزارة الموارد البشرية والتنمية الاجتماعية',1 FROM "ncnp_classifications" WHERE "code"='G04-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A01-B02',3,"id",'خدمات الشباب والنشء','المنظمات التي تقدم خدمات الشباب والنشء والرعاية الشبابية ، بما في ذلك خدمات منع الجنوح والانحراف الخلقي، ومنع التسرب من الدراسة، ومراكز ونوادي الشباب وبرامج فرص العمل للشباب، وتشمل بيوت الشباب والكشافة ونحوها.','وزارة الموارد البشرية والتنمية الاجتماعية',2 FROM "ncnp_classifications" WHERE "code"='G04-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A01-B03',3,"id",'خدمات الأسرة','المنظمات التي توفر الخدمات التثقيفية والإرشاد الأسري للوالدين.','وزارة الموارد البشرية والتنمية الاجتماعية',3 FROM "ncnp_classifications" WHERE "code"='G04-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A01-B04',3,"id",'خدمات الحماية الأسرية','المنظمات التي توفر المراكز والدور التي تهتم بالأمهات اللاتي يرعون أبناءهن بمفردهن (مطلقات - أرامل ) وخدمات الإيواء والحماية من العنف المنزلي.','وزارة الموارد البشرية والتنمية الاجتماعية',4 FROM "ncnp_classifications" WHERE "code"='G04-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A01-B05',3,"id",'خدمات ذوي الاحتياجات الخاصة','المنظمات التي تقدم خدمات (غير طبية) لذوي الاحتياجات الخاصة وتشمل أماكن الإيواء (غير دور الرعاية الصحية) وخدمات المواصلات والترفيه والخدمات الشخصية الأخرى.','وزارة الموارد البشرية والتنمية الاجتماعية',5 FROM "ncnp_classifications" WHERE "code"='G04-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A01-B06',3,"id",'خدمات المسنين','المنظمات التي تقدم رعاية للمسنين (غير طبية)، بما في ذلك الخدمات التي تقدم في المنزل، وخدمات الأعمال المنزلية والنقل والترفيه وبرامج الوجبات الغذائية والخدمات الأخرى الموجَّهة نحو كبار السن (لا تدخل فيها دور رعاية الصحية للمسنين)','وزارة الموارد البشرية والتنمية الاجتماعية',6 FROM "ncnp_classifications" WHERE "code"='G04-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A01-B07',3,"id",'خدمات تعزيز الاعتماد على الذات والخدمات الاجتماعية الأخرى للأفراد','برامج تعزيز القدرة على الاعتماد على الذات والتنمية الشخصية، بما في ذلك مجموعات الدعم وتقديم الاستشارات الشخصية وتقديم المشورة فيما يتصل بالادخار والإتمان وإدارة المال.','وزارة الموارد البشرية والتنمية الاجتماعية',7 FROM "ncnp_classifications" WHERE "code"='G04-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A01-B08',3,"id",'خدمات النقل لأشخاص ذوي الأ‘عاقه','المنظمات التي تقدم جميع خدمات النقل لأشخاص ذوي الاعاقه ( النقل البري - النقل الجوي - النقل البحري - النقل السككي )','وزارة النقل والخدمات اللوجستية',8 FROM "ncnp_classifications" WHERE "code"='G04-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A01-B09',3,"id",'خدمات أبحاث النقل والسلامة','المنظمات المختصة بالبحث العلمي وتبادل المعلومات في مجالات النقل البري والبحري والسككي زالجوي والطرق والسلامة ونشر الوعي العلمي وتشجيع الممارسات البحثية','وزارة النقل والخدمات اللوجستية',9 FROM "ncnp_classifications" WHERE "code"='G04-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A01-B10',3,"id",'خدمات النقل للمسنين','المنظمات التي تقدم جميع خدمات النقل للمسنين فيما يخدم تنقلاتهم (النقل البري - النقل الجوي - النقل البحري - النقل السككي )','وزارة النقل والخدمات اللوجستية',10 FROM "ncnp_classifications" WHERE "code"='G04-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G04-A02',2,"id",'الطوارئ والإغاثة',2 FROM "ncnp_classifications" WHERE "code"='G04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A02-B01',3,"id",'خدمات الإغاثة والطوارئ','المنظمات التي تعمل على الوقاية من الكوارث والتنبؤ بها والسيطرة عليها وتخفيف آثارها، وإرشاد الأفراد وإعدادهم للتعامل مع آثارها، أو تقديم الإغاثة لضحايا الكوارث،وتشمل فرق التطوع المشاركة في مكافحة الحرائق و السيول والغرق، ونحوها','وزارة الداخلية',1 FROM "ncnp_classifications" WHERE "code"='G04-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G04-A03',2,"id",'دعم الدخل وصيانته',3 FROM "ncnp_classifications" WHERE "code"='G04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A03-B01',3,"id",'خدمات دعم الدخل','المنظمات التي تقدم مساعدات نقدية وغيرها من صور الخدمات المباشرة إلى الأشخاص غير القادرين على امتلاك سبل العيش.','وزارة الموارد البشرية والتنمية الاجتماعية',1 FROM "ncnp_classifications" WHERE "code"='G04-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G04-A03-B02',3,"id",'خدمات المساعدات المادية العينية','المنظمات التي تقدم الأغذية والملابس والنقل وغيرها من أشكال المساعدة، بما في ذلك بنوك الطعام وحفظ النعمة ومراكز توزيع الملابس.','وزارة البلديات والإسكان',2 FROM "ncnp_classifications" WHERE "code"='G04-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") VALUES ('G05',1,NULL,'المجموعة الخامسة البيئة (المنظمات التي تعزز وتوفر الخدمات التي تٌعنى بالمحافظة على البيئة ومكافحة التلوث والوقاية والتثقيف البيئي والصحي، وحماية الحيوان)',5);
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G05-A01',2,"id",'البيئة',1 FROM "ncnp_classifications" WHERE "code"='G05';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G05-A01-B01',3,"id",'خدمة الحفاظ على الموارد المائية','الحفاظ على الموارد المائية وحمايتها ، بما في ذلك السدود والابار وجميع مصادر المياه','وزارة البيئة والمياه والزراعة',1 FROM "ncnp_classifications" WHERE "code"='G05-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G05-A01-B02',3,"id",'خدمات الحد من التلوث ومكافحته','المنظمات التي تدعو إلى نظافة الهواء والماء وتقليل تلوث الضوضاء والسيطرة على الإشعاع ومعالجة النفايات الخطرة والمواد السامة وإدارة النفايات الصلبة وبرامج التدوير','وزارة البيئة والمياه والزراعة',2 FROM "ncnp_classifications" WHERE "code"='G05-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G05-A01-B03',3,"id",'خدمات الحفاظ على الموارد الطبيعية وحمايتها','الحفاظ على الموارد الطبيعية وحمايتها، بما في ذلك الأراضي والطاقة والموارد النباتية للاستعمال العام والتمتع بالحياة','وزارة البيئة والمياه والزراعة',3 FROM "ncnp_classifications" WHERE "code"='G05-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G05-A01-B04',3,"id",'خدمات تجميل وتخطيط المناطق الحضرية','المنظمات التي تقدم برامج تخطيط وتجميل المدن ، ومن ذلك خدمات تجميل الأحياء والطرق ، وبرامج الحفاظ على الحدائق والمساحات الخضراء والمفتوحة في المناطق الحضرية والريفية ، وتنظيم حملات لمكافحة إلقاء المهملات ومعالجة التشوه البصري وتحسين مظهر المدينة ، وكذلك المنظمات التي تعنى بتقديم البرامج والخدمات في مجال السياسات البلدية والقروية ، وتخطيط المدن .','وزارة البلديات والإسكان',4 FROM "ncnp_classifications" WHERE "code"='G05-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G05-A01-B05',3,"id",'المركبات الكهربائية','المنظمات االمختصة في مجال المركبات التي تعمل على الطاقة بهدف الحفاظ على البيئة','وزارة النقل والخدمات اللوجستية',5 FROM "ncnp_classifications" WHERE "code"='G05-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G05-A01-B06',3,"id",'الحد من مخلفات البيئيه والإنبعاثات الكربونية الناتجه من وسائل النقل وقطاع إنشاء وصيانة الطرق وما يسببه من أضرار للبيئة','المنظمات التي تدعو الى نظافة الهواء ,والطرق والتلوث الناتج عن جميع وسائل النقل وإنشاء وصيانة الطرق','وزارة النقل والخدمات اللوجستية',6 FROM "ncnp_classifications" WHERE "code"='G05-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G05-A02',2,"id",'حماية الحيوان والبيئة',2 FROM "ncnp_classifications" WHERE "code"='G05';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G05-A02-B01',3,"id",'خدمات حماية ورعاية الحيوان والخدمات البيطرية','خدمات حماية الحيوانات والمحافظة عليها و الرفق به بما في ذلك ملاجئ الحيوان والمستشفيات والعيادات البيطرية والخدمات التي تقدم لرعاية الحيوانات الأليفة في المزرعة والمنزل','وزارة البيئة والمياه والزراعة',1 FROM "ncnp_classifications" WHERE "code"='G05-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G05-A02-B02',3,"id",'خدمات الحماية والحفاظ على الحياة البرية','الحفاظ على البيئة البرية وحمايتها، بما في ذلك المحميات والملاجئ الطبيعية','وزارة البيئة والمياه والزراعة',2 FROM "ncnp_classifications" WHERE "code"='G05-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G05-A03',2,"id",'حفظ النعمة',3 FROM "ncnp_classifications" WHERE "code"='G05';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G05-A03-B01',3,"id",'حفظ النعمة (الغذاء)','منظمات تعني بحفظ النعمة (الغذاء ) بطريقة مبتكرة للاستفادة من الفائض والفاقد وفق الأشتراطات الصحية والفنية وتوزيعة على المحتاجين، بما في ذلك جمعيات حفظ النعمة الغذاء وبنوك الطعام لتقديم خدمات ومبادرات تكافلية اجتماعية وتوعية بكفاءة عالية','وزارة البيئة والمياه والزراعة',1 FROM "ncnp_classifications" WHERE "code"='G05-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") VALUES ('G06',1,NULL,'المجموعة السادسة التنمية و الإسكان (المنظمات التي تعزز البرامج و الخدمات للمساعدة في تحسين المجتمعات وتحقيق الرفاه الاقتصادي والاجتماعي للمجتمع)',6);
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G06-A01',2,"id",'التنمية الاجتماعية والاقتصادية والمجتمعية',1 FROM "ncnp_classifications" WHERE "code"='G06';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A01-B01',3,"id",'خدمات المجتمعات المحلية والأحياء والمرافق العامة','المنظمات التي تعنى بتحسين جودة ونوعية الحياة في إطار المجتمعات والأحياء ، بما في ذلك إنشاء وإدارة المرافق العامة مثل الحدائق والساحات العامة ومرافق تجهيز الموتى والمقابر والشوارع والأرصفة ودورات المياه العامة والمتنقلة وغيرها','وزارة البلديات والإسكان',1 FROM "ncnp_classifications" WHERE "code"='G06-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A01-B02',3,"id",'الفندقة ودور الضيافة السياحية','المنظمات التي تعمل في إدارة وإنشاء وتشغيل الفنادق ودور الضيافة السياحية','وزارة السياحة',2 FROM "ncnp_classifications" WHERE "code"='G06-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A01-B03',3,"id",'منظمات دعم ريادة الاعمال','المنظمات التي تعنى بتمكين رواد الأعمال لبدء مشاريعهم وتنميتها، وتوفير وسائل لتحفيز رواد الأعمال ومعالجة التحديات التي تواجه مشاريعهم الناشئة وتسهم في تحقيق نجاحها واستدامتها. وإيجاد بيئة استثمار جاذبة ومستدامة من المبادرات مثل التدريب والإرشاد وحلول التمويل والاستثمار، وتقديم برامج الاحتضان ومسرعات الأعمال و تنفيذ ودعم البرامج والمشاريع و نشر ثقافة وفكر العمل الحر ريادة الأعمال ، توفير مساحة للعمل وخدمات لتطوير الأعمال وخدمات إستشارية وتوجيهية وتدريبية وتوفير مساحات عمل مشتركة لتسريع نمو الاعمال الريادية الناشئة.','وزارة التجارة',3 FROM "ncnp_classifications" WHERE "code"='G06-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A01-B04',3,"id",'منظمات النقل البري','المنظمات التي تعنى بالمهمات التنظيمية والتنفيذية المتعلقة بمجال النقل البري (سائقي الأجرة - نقل البضائع - النقل البري)','وزارة النقل والخدمات اللوجستية',4 FROM "ncnp_classifications" WHERE "code"='G06-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A01-B05',3,"id",'خدمات تنظيم المؤتمرات والمعارض','هي المنظمات التي تعمل في مجال إدارة وتشغيل وتنظيم صناعة الاجتماعات (المعارض والمؤتمرات) وتأهيل العاملين عليها','وزارة التجارة',5 FROM "ncnp_classifications" WHERE "code"='G06-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A01-B06',3,"id",'خدمات التنمية الاجتماعية','المنظمات التي تعمل على تحسين البنية الأساسية المؤسسية والقدرات من أجل تخفيف المشاكل الاجتماعية وتحسين حياة أفراد المجتمع','وزارة الموارد البشرية والتنمية الاجتماعية',6 FROM "ncnp_classifications" WHERE "code"='G06-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A01-B07',3,"id",'خدمات التنمية الاقتصادية','البرامج والخدمات التي تهدف إلى تحسين البنية التحتية الاقتصادية والقدرات، بما في ذلك بناء المرافق الأساسية مثل الطرق، والخدمات المالية مثل خدمات الائتمان والادخار، وبرامج المشاريع الصغيرة، الاستشارات الفنية والإدارية والمساعدات الإنمائية الريفية','وزارة الاقتصاد والتخطيط',7 FROM "ncnp_classifications" WHERE "code"='G06-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G06-A02',2,"id",'المسؤولية الاجتماعية',2 FROM "ncnp_classifications" WHERE "code"='G06';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A02-B01',3,"id",'المسؤولية الاجتماعية','المنظمات التي تساهم في تعزيز برامج المسؤولية الاجتماعية في القطاع الخاص','وزارة الموارد البشرية والتنمية الاجتماعية',1 FROM "ncnp_classifications" WHERE "code"='G06-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G06-A03',2,"id",'الاسكان',3 FROM "ncnp_classifications" WHERE "code"='G06';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A03-B01',3,"id",'خدمات التشييد و التمويل السكنية','تعمير وتشييد وإدارة وتمويل و المساكن وتأجيرها و الإسكان بالقرى و الهجر و الادخار السكني','وزارة البلديات والإسكان',1 FROM "ncnp_classifications" WHERE "code"='G06-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A03-B02',3,"id",'خدمات مساعدة الإسكان','المنظمات التي تقوم بأبحاث في مجال الإسكان أو تقدم خدمات استشارية او قانونية أو تصميمة أو غيرها من الخدمات التي تتصل بالإسكان','وزارة البلديات والإسكان',2 FROM "ncnp_classifications" WHERE "code"='G06-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A03-B03',3,"id",'خدمات التشغيل والصيانة وإدارة المرافق','المنظمات التي تقوم بتقديم الخدمات التشغيلية للمباني وصيانتها وترميمها وادارتها و الأربطة السكنية','وزارة البلديات والإسكان',3 FROM "ncnp_classifications" WHERE "code"='G06-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A03-B04',3,"id",'خدمات دعم المتعثرين والترميم و الإيواء','المنظمات التي تقوم بدعم المتعثرين ومساكن مستفيدي الضمان بالسداد وتمويلهم و ترميم المنازل العشوائية و خدمات الإيواء المؤقت','وزارة البلديات والإسكان',4 FROM "ncnp_classifications" WHERE "code"='G06-A03';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G06-A04',2,"id",'العمل والتدريب',4 FROM "ncnp_classifications" WHERE "code"='G06';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A04-B01',3,"id",'خدمات برامج التدريب على العمل','المنظمات التي تقدم وترعى برامج التلمذة الصناعية والمنح الداخلية والتدريب على العمل وغيرها من برامج التدريب','وزارة الموارد البشرية والتنمية الاجتماعية',1 FROM "ncnp_classifications" WHERE "code"='G06-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A04-B02',3,"id",'منظمات تدريب الطيران','لمنظمات التي تعمل في تنظيم وتنفيذ برامج تدريب الطيران و نشر ثقافة الطيران بجميع أنواعه وتقديم منح التدريب على العمل في مجال الطيران','وزارة النقل والخدمات اللوجستية',2 FROM "ncnp_classifications" WHERE "code"='G06-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A04-B03',3,"id",'منظمات تدريب وتأهيل الغوص والسباحة والكوادر البحرية','المنظمات التي تعمل في مجال تدريب السباحة والغوص وتأهيل وتدريب الكوادر البحرية وتطويرها','وزارة النقل والخدمات اللوجستية',3 FROM "ncnp_classifications" WHERE "code"='G06-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A04-B04',3,"id",'خدمات الإرشاد والتوجيه المهني','التدريب المهني والتوجيه والإرشاد فيما يخص المستقبل الوظيفي والاختبارات وغير ذلك من الخدمات','وزارة الموارد البشرية والتنمية الاجتماعية',4 FROM "ncnp_classifications" WHERE "code"='G06-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A04-B05',3,"id",'خدمات التأهيل المهني والورش للأشخاص ذوي الإعاقة','المنظمات الي تعمل على تحقيق الاكتفاء الذاتي وتوليد الدخل عن طريق التدريب وخلق فرص العمل','وزارة الموارد البشرية والتنمية الاجتماعية',5 FROM "ncnp_classifications" WHERE "code"='G06-A04';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G06-A05',2,"id",'المسؤولية الاجتماعية في قطاع النقل',5 FROM "ncnp_classifications" WHERE "code"='G06';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G06-A05-B01',3,"id",'منظمات المسؤولية الاجتماعية في قطاع النقل البري والجوي والبحري والسككي','المنظمات التي تساهم في تعزيز برامج المسؤولية الاجتماعية في قطاعات النقل البري والجوي والبحري والسككي والخدمات اللوجستية','وزارة النقل والخدمات اللوجستية',1 FROM "ncnp_classifications" WHERE "code"='G06-A05';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") VALUES ('G07',1,NULL,'المجموعة السابعة التأييد والمؤازرة(المنظمات التي تعمل على حماية وتعزيز حقوق فئات معينة، تقديم الخدمات القانونية وتعزيز السلامة العامة)',7);
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G07-A01',2,"id",'منظمات التوعية التأييد والمؤازرة',1 FROM "ncnp_classifications" WHERE "code"='G07';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A01-B01',3,"id",'الوقاية من المخدرات','المنظمات التي تقدم برامج وقائية بأضرار المخدرات و الاستشارات الاسرية والرعاية اللاحقة للمتعافين وتأهيلهم','وزارة الداخلية',1 FROM "ncnp_classifications" WHERE "code"='G07-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A01-B02',3,"id",'التوعية و التأييد والمؤازرة','المنظمات الي تدعو إلى التوعية وحماية حقوق واهتمامات فئات معيَّنة مثل المعاقين جسدياً وكبار السن والأطفال والنساء','وزارة الموارد البشرية والتنمية الاجتماعية',2 FROM "ncnp_classifications" WHERE "code"='G07-A01';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") SELECT 'G07-A02',2,"id",'الخدمات القانونية',2 FROM "ncnp_classifications" WHERE "code"='G07';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B01',3,"id",'أنشطة اخرى خاصة بالأنشطة القانونية','تقديم الخدمات الأخرى المتعلقة بالقانون','وزارة العدل',1 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B02',3,"id",'خدمات السلامة العامة','منع الجريمة من أجل السلامة العامة وتوعية المجتمع بالإجراءات الوقائية','وزارة الداخلية',2 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B03',3,"id",'المنظمات التي تعمل في مجال الامن والسلامة في السكك الحديدية','المنظمات التي تعمل على توعية المجتمع في الامن والسلامة السكك الحديدية المنظمات المعنية بالاهتمام بالسكك الحديدة رفع واستقبال البلاغات الخاصة بالبنية التحتية للسكك الحديدية','وزارة النقل والخدمات اللوجستية',3 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B04',3,"id",'خدمات تأهيل الجانحين والأحداث','البرامج والخدمات التي تهدف إلى إعادة إدماج الجانحين، بما في ذلك دور الملاحظة والإسكان المؤقت','وزارة الموارد البشرية والتنمية الاجتماعية',4 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B05',3,"id",'السلامة المرورية وسلامة الطرق السريعة','المنظمات التي تعمل على توعية المجتمع في الامن والسلامة في الطرق السريعة والمنظمات التي تعمل على الاهتمام في الطرق السريعة ورفع واستقبال البلاغات الخاصة بالبنية التحتية للطرق','وزارة النقل والخدمات اللوجستية',5 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B06',3,"id",'منع الجرائم','الخدمات التي تقدم برامج وقائية لمنع الجرائم ومعالجة الأسباب المؤدية لها','وزارة الداخلية',6 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B07',3,"id",'السلامة المرورية','التوعية بالطرق الوقائية من الحوادث المرورية','وزارة الداخلية',7 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B08',3,"id",'خدمات تأهيل المجرمين','الخدمات التي تعمل على تأهيل المفرج عنهم وتأهيلهم للاندماج مع المجتمع','وزارة الداخلية',8 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B09',3,"id",'منظمات المعايير والمقاييس','المنظمات التي تعنى بالمهمات التنظيمية والتنفيذية المتعلقة بالمواصفات والمقاييس والجودة ،والمعايير والاشتراطات والمتطلبات الفنية الواجب توفرها في السلع والمنتجات لتحقيق الحد المقبول من الجودة للحفاظ على صحة وسلامة المستهلك ،وإجراءات تقويم المطابقة الاختبار وأنظمة الجودة ،و تنفيذ التصنيفات القياس والمعايرة في مجالات القياس المختلفة .','وزارة التجارة',9 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B10',3,"id",'منظمات الابتكار والاختراع','المنظمات التي تعنى بدعم الابتكار والمبتكرين والاختراع والمخترعين لتمكينهم ، وتنميتهم، ورعايتهم وحمايته حقوقهم وتوفير وسائل التحفيز والدعم والمساهمة بالارتقاء بهم وفق أفضل الممارسات','الهيئة السعودية للملكية الفكرية',10 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B11',3,"id",'منظمات الاستشارات المحسابىة','المنظمات المساهمةالتي تعنى بتقديم خدمات المحاسبة من خلال المعارف والمهارات المتوفرة بريادة مهنة المحاسبة والمراجعة والإشراف عليها لتطوير ودعم الأفراد والمؤسسات والمجموعات المختلفة ذات العلاقة بالعمل التجاري بهدف تزويدها بما يلزم لتحقيق القدرات الاقتصادية التي تمكن منشآتها من الاستمرار في العمل .','وزارة التجارة',11 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B12',3,"id",'منظمات التقييم السلع والخدمات ومعادن','قديم الدراسات والبحوث والاستشارات التي تساعد في تطوير مهنة التقييم وفقاً للقواعد والمعايير المنظمة لها، ودعم الأفراد والمؤسسات والمجموعات المختلفة ذات العلاقة بالتعاون مع الجهات المنظمة للمهنة لتمكينهم من الاستمرارية في مزاولة المهنة، ورفع الوعي المجتمعي لتعزيز الثقة بالمهنة والمقيمين"','وزارة التجارة',12 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B13',3,"id",'منظمات حماية الملكية الفكرية','المنظمات التي تعنى بالحماية الملكية الفكرية و تنظيم مجالات الملكية الفكرية في المملكة، ودعمها، وتنميتها، ورعايتها، وحمايتها، وانفاذها، والتوعية بأهمية الملكية الفكرية، وحماية حقوقها للمساهمةبالارتقاء بها وفق أفضل الممارسات .','الهيئة السعودية للملكية الفكرية',13 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B14',3,"id",'خدمات تقديم الدعم لضحايا الاعتداءات والجرائم','الخدمات والمشورة المقدمة لدعم ضحايا الجرائم','وزارة الداخلية',14 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B15',3,"id",'حماية المستهلك','حماية حقوق المستهلك وتحسين مراقبة الإنتاج ونوعيته','وزارة التجارة',15 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G07-A02-B16',3,"id",'المحاماة والاستشارات القانونية','تقديم الخدمات القانونية والمشورة والمساعدة في حل النزاعات والمسائل المتصلة بالمحاكم وتنفيذ أحكام الرؤية والزيارة والحضانة','وزارة العدل',16 FROM "ncnp_classifications" WHERE "code"='G07-A02';
INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","display_order") VALUES ('G08',1,NULL,'المجموعة الثامنة منظمات دعم العمل الخيري (المنظمات التي تقدم أنواع الدعم المختلفة للعمل الخيري والتطوعي)',8);
