INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G10-A03-B01',3,"id",'الثروة الزراعية','هي المنظمات الداعمة والمنظمة لأعمال قطاع الثروة الزراعية والنحالين وبحث وتطوير الأنشطة وتنفيذها لتنميتهم لخدمة المجتمع','وزارة البيئة والمياه والزراعة',1 FROM "ncnp_classifications" WHERE "code"='G10-A03';
