INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G10-A03-B03',3,"id",'الثروة الحيوانية','هي المنظمات الداعمة والمنظمة لأعمال قطاع الثروة الحيوانية ( الماشية والدواجن والإبل ) وبحث وتطوير الأنشطة وتنفيذها لتنميتهم لخدمة المجتمع','وزارة البيئة والمياه والزراعة',3 FROM "ncnp_classifications" WHERE "code"='G10-A03';
