INSERT INTO "ncnp_classifications" ("code","level","parent_id","name","definition","supervising_entity","display_order") SELECT 'G10-A04-B01',3,"id",'الصناعة والثروة المعدنية','هي المنظمات الداعمة والمنظمة لأعمال الصناعة والثروة المعدنية والمُساهمة في تنمية و تطوير الأنشطة و تحفيز الابتكار بما يحقق التنوع و يعود على المجتمع بالمنفعة .','وزارة الصناعة والثروة المعدنية',1 FROM "ncnp_classifications" WHERE "code"='G10-A04';
