-- GEN-07 (UAT Fix List v1.4): NCNP Non-Profit Entity Classification.
-- Replaces the entity-level "Sector" field. A 3-level reference list
-- (Group > Level A > Level B) loaded from NCNP's official classification
-- workbook (10 groups / 34 Level A / 123 Level B). An organisation stores its
-- Level B item; Group and Level A are derived through parent_id.
-- Platform-wide reference data like regions/area_profiles: no org_id, no RLS.
-- Maintained by the System Admin afterwards (items are deactivated, never
-- deleted, so an organisation's stored classification always resolves).
-- The list is Arabic only; the Arabic value is shown in both languages.
-- Source fixes applied while generating: Group / Level A filled down, extra
-- spaces trimmed, the stray "C50" cell outside the table ignored.

CREATE TABLE "ncnp_classifications" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "code" VARCHAR(20) NOT NULL,
    "level" SMALLINT NOT NULL,
    "parent_id" UUID,
    "name" VARCHAR(300) NOT NULL,
    "definition" TEXT,
    "supervising_entity" VARCHAR(300),
    "display_order" INTEGER NOT NULL DEFAULT 0,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "ncnp_classifications_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "ncnp_classifications_level_check" CHECK ("level" IN (1, 2, 3)),
    CONSTRAINT "ncnp_classifications_parent_id_fkey" FOREIGN KEY ("parent_id") REFERENCES "ncnp_classifications"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE UNIQUE INDEX "ncnp_classifications_code_key" ON "ncnp_classifications"("code");
CREATE INDEX "ncnp_classifications_parent_id_idx" ON "ncnp_classifications"("parent_id");

GRANT SELECT, INSERT, UPDATE ON "ncnp_classifications" TO cnap_app;
GRANT SELECT ON "ncnp_classifications" TO cnap_supervisor;

ALTER TABLE "organisations" ADD COLUMN "ncnp_classification_id" UUID;
ALTER TABLE "organisations" ADD CONSTRAINT "organisations_ncnp_classification_id_fkey" FOREIGN KEY ("ncnp_classification_id") REFERENCES "ncnp_classifications"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE INDEX "organisations_ncnp_classification_id_idx" ON "organisations"("ncnp_classification_id");

-- NCNP official list: 10 groups, 34 Level A, 123 Level B.
